## Reimports explicitly leased model paths without scanning active source workers.
func reimport_models(paths: PackedStringArray) -> Dictionary:
	EditorInterface.get_resource_filesystem().reimport_files(paths)
	var resolved: Array[String] = []
	for path: String in paths:
		assert(FileAccess.file_exists(path + ".import"), path)
		resolved.append(path)

	return {"resolved": resolved}


